import itertools
import math

def sign(pi):
    # pi is a tuple representing the permutation mapping (i+1 -> pi[i])
    # Using cycle decomposition for sign is robust, but bubble sort swaps count is simpler here
    n = len(pi)
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if pi[i] > pi[j]:
                inversions += 1
    return 1 if inversions % 2 == 0 else -1

def calculate_Sm(m):
    # Generate all permutations of {1, 2, ..., m}
    perms = list(itertools.permutations(range(1, m + 1)))

    # Filter for derangements (no fixed points)
    derangements = []
    for p in perms:
        is_derangement = True
        for i in range(m):
            # Check if p[i] maps i+1 to i+1
            if p[i] == i + 1:
                is_derangement = False
                break
        if is_derangement:
            derangements.append(p)

    # Calculate the sum of signs
    total_sign = 0
    for p in derangements:
        total_sign += sign(p)
    return total_sign

# Calculate S_4
S4 = calculate_Sm(4)
print(f"S_4 = {S4}")
